```javascript
const jobStatus = "queued";

function report(response) {
  const httpStatus = response.status;
  if (httpStatus >= 400) {
    const message = `Request failed with ${httpStatus}`;
    return message;
  }
  return `Job is ${jobStatus}`;
}

console.log(report({ status: 200 })); // Job is queued
```
